from .facade import DefensicsConnection
from taf.internal.robot_typecasts import time_to_seconds  # type: ignore


class defensics(object):
    """
    Usage example:
        >>> from taf.sw.security.defensics import defensics
        >>> defensics_object = defensics()
        >>> defensics_object.connect_to('10.44.149.44', 5900)
        >>> defensics_object.load_suite(file="/opt/Synopsys/Defensics/bt-a2dp-5.3.0/testtool/bt-a2dp-530.jar",
        >>>                             name="https", use_newest=True, timeout= 10)
        u'Loading suite bt-a2dp-5.3.0/testtool/bt-a2dp-530.jar.'
    """

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    def __init__(self):
        self._defensics_connection = None

    def connect_to(self, ip_address, port, token=None, defensics_version="defensics_v2020_3", secure=False):
        """
        Provides connection and authorization to Defensics.

        :param str ip_address: IP address to proper host, e.g. ``10.44.44.1``.
        :param int port: Port for connection to Defensics, e.g. ``5900``.
        :param Optional[str] token: To prevent the service from being wide open to any callers, token authentication
            should be used. When defensics starts with flag ``--enable-token-auth`` it generates a token.
        :param Optional[str] defensics_version: Default: ``defensics_v2020_3``. Specifies version of the Defensics.
            Currently supported options: [``defensics_v2020_3``].
        :param Optional[bool] secure: Default ``False``. If set to ``True``, the connection will be realized
            with use https prefix, else with http. Currently, only http can be used.
        :return: It returns ``DefensicsConnection`` instance.
        """
        self._defensics_connection = DefensicsConnection(
            ip_address=ip_address, port=port, token=token, defensics_version=defensics_version, secure=secure
        )

        return self._defensics_connection

    def load_suite(self, suite_file, name=None, use_newest=True, timeout=10):
        """
        Method for suite loading. Notice that suite loading can take time, and if for example state
        is asked immediately after load command the suite is not yet loaded and thus is not visible in the response.

        :param str suite_file: name of suite, e.g., ``/opt/Synopsys/Defensics/bt-a2dp-5.3.0/testtool/bt-a2dp-530.jar``
        :param Optional[str] name: if given suite can be controlled using shorter suite name
        :param Optional[bool] use_newest: If set to ``True``, the newest installed suite will be loaded.
            Defaults to ``True``
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: It returns str with information that suite load process has started
        """
        return self._defensics_connection.load_suite(
            suite_file=suite_file, name=name, use_newest=use_newest, timeout=time_to_seconds(timeout, round_to=0)
        )

    def get_installed_suites(self, timeout=10):
        """
        Method to get list of all installed suites

        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: It returns list of currently installed suites
        """
        return self._defensics_connection.get_installed_suites(timeout=time_to_seconds(timeout, round_to=0))

    def start_plan(self, run_sequentially=False, timeout=10):
        """
        Execute all loaded suites

        :param Optional[Union[bool,str]] run_sequentially: Determines if suites are executed one by one (``True``)
            or in parallel (``False``, default)
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return:
        """

        return self._defensics_connection.start_plan(
            run_sequentially=run_sequentially, timeout=time_to_seconds(timeout, round_to=0)
        )

    def stop_plan(self, timeout=10):
        """
        Stop execution of the plan

        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return:
        """

        return self._defensics_connection.stop_plan(timeout=time_to_seconds(timeout, round_to=0))

    def start_suite(self, name=None, timeout=10):
        """
        Execute a suite specified by its name. If there is only one suite loaded, name is not needed.

        :param Optional[str] name: Short name of the suite
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: str: Server's response message, e.g., ``Test suite https started``
        """

        return self._defensics_connection.start_suite(name=name, timeout=time_to_seconds(timeout, round_to=0))

    def stop_suite(self, name=None, timeout=10):
        """
        Stop execution of a suite specified by its name. If there is only one suite loaded, name is not needed.

        :param Optional[str] name: Short name of the suite
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return:
        """

        return self._defensics_connection.stop_suite(name=name, timeout=time_to_seconds(timeout, round_to=0))

    def resume_suite(self, suite, test_run=None, resume_index_offset=None, timeout=10):
        """
        Resume a stopped run. By default, suite's most recent test run is resumed.
        Suite must be loaded.

        :param str suite: ??
        :param Optional[str] test_run: Defines explicitly a test run to resume,
            e.g., ``HTTP-Server/20160207-0934-45``
        :param Optional[Union[int,str]] resume_index_offset: Can be used to define where the test run is resumed,
            e.g., 10 resumes the defined test run 10 test cases ahead where it ended
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: str: Server's response message, e.g, ``Test suite HTTP-Server's test run 20110207-0934-45 resumed``
        """

        return self._defensics_connection.resume_suite(
            suite=suite,
            test_run=test_run,
            resume_index_offset=resume_index_offset,
            timeout=time_to_seconds(timeout, round_to=0),
        )

    def pause_suite(self, name=None, timeout=10):
        """
        Pause a suite specified by its short name; it can be continued with ``Start Suite``.
            If there is only one suite loaded, name is not needed.

        :param Optional[str] name: Short name of the suite
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: str: Server's response message, e.g., ``Test suite https paused``
        """
        return self._defensics_connection.pause_suite(name=name, timeout=time_to_seconds(timeout, round_to=0))

    def get_suite_status(self, name=None, timeout=10):
        """
        Method to get the status of a suite.
        Raises ``RuntimeError`` if ``name`` was not passed and there is more than one loaded suite.

        :param Optional[str] name: Short name of the suite given when it was loaded.
            Can be omitted if there is only one suite loaded
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: Returns str with the following possible values: ``Idle``, ``Running``, ``Finished`` and ``Failed``
        """
        return self._defensics_connection.get_suite_status(name=name, timeout=time_to_seconds(timeout, round_to=0))

    def get_testing_status(self, timeout=10):
        """
        Method to get the state of an ongoing test run.
        Raises ``RuntimeError`` if the server returned an empty string, which can be caused by no suite being loaded.
        Raises ``ValueError`` if the server returned data that cannot be converted to a list of ``TestState`` objects.

        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: Returns the state of an ongoing test run, executed cases and remaining cases time estimate in the form
            of a dictionary of ``TestState`` objects. Each ``TestState`` can be accessed by short name of the suite.
        """
        return self._defensics_connection.get_testing_status(timeout=time_to_seconds(timeout, round_to=0))

    def rerun_suite(
        self,
        suite=None,
        suite_name=None,
        file_path=None,
        load_suite=None,
        setting=None,
        verdict=None,
        type_of_rerun=None,
        instrumentation=None,
        rerun_preceding=None,
        timeout=10,
    ):
        """
        Rerun groups of failed test cases of last test run.

        :param Optional[str] suite: The suite jar file. Defines suite which most recent test run is rerun. File can be
            absolute, relative to suite installation dir, or just the jar file, e.g., ``http-server-320.jar``
        :param Optional[str] suite_name: Name of the loaded suite which is used in rerun, or which most recent
            results are rerun if there is not file defined, e.g., ``HTTP-Server``
        :param Optional[str] file_path: defines which results are rerun, e.g., ``HTTP-Server/20130201-1315-44``
        :param Optional[Union[str,bool]] load_suite: If true, forces to load a new suite to be used in rerun.
        :param Optional[str] setting: Overwritten settings, in same format as in ``set-setting`` command,
            e.g., ``--uri 127.0.0.1:8080``
        :param Optional[str] verdict: a space or comma separated list of test verdicts to rerun. Possible values:
            ``pass``, ``fail``, ``denial-of-service``, ``n/a``, ``no-interop``, ``skip``, ``degradation-of-service``,
            ``user-stop``, ``suite-error``, ``aborted``
        :param Optional[str] type_of_rerun: possible values: ``index``, ``hash``, ``group``
        :param Optional[str] instrumentation: Defines instrumentation method(s) (space or comma separated list)
            which results are used to resolve failures. Possible values (By default, ``valid-external`` is used):
            ``all``, ``valid-external``, ``valid``, ``external``, ``connection``, ``snmp``, ``snmptrap``,
            ``isasecure``, ``safeguard``, ``syslog``
        :param Optional[Union[int,str]] rerun_preceding: Can be used to pick cases before failure to rerun test cases.
            Note that option works only with ``index`` type rerun. For example, ``rerun_preceding=10``
            picks failed cases and 10 preceding cases for each failure.
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return:
        """
        return self._defensics_connection.rerun_suite(
            suite=suite,
            suite_name=suite_name,
            file_path=file_path,
            load_suite=load_suite,
            setting=setting,
            verdict=verdict,
            type_of_rerun=type_of_rerun,
            instrumentation=instrumentation,
            rerun_preceding=rerun_preceding,
            timeout=time_to_seconds(timeout, round_to=0),
        )

    def get_suite_settings(self, name=None, timeout=10):
        """
        Method to get all settings of given suite. Settings which are enabled are marked with ``X``.
        Raises ``RequestFailed`` exception if given suite name is not found or no suite name was provided
            while more than one is loaded on the server.

        :param Optional[str] name: Short name of the suite given when it was loaded.
            Can be omitted if there is only one suite loaded
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return str: Returns string with all settings displayed. Newlines in string are marked with ``\\n``
        """
        return self._defensics_connection.get_suite_settings(name=name, timeout=time_to_seconds(timeout, round_to=0))

    def set_suite_settings(self, name, *args, **kwargs):
        """
        Method to set settings of given suite. Settings should be passed in the same form as they are in Defensics CLI
        ``--set method``. One setting is passed in separate argument.
        BEWARE! Defensics API doesn't recognize if parameter name is wrong. Tester needs to verify it for themselves
        Raises ConnectionFailed if given suite name is not found or if no parameters was given (HTTP RC 104)
        Raises RequestFailed if given parameter value is wrong (doesn't match accepted values list, HTTP RC 501)

        :param str name: Short name of the loaded suite
        :param args: Suite settings which can be passed as separate args respectively
        :param kwargs: Suite timeout in seconds which is passed via keyword arguments in form timeout=20 (default value
            is 10)
        """
        timeout = kwargs.get("timeout", 10)
        return self._defensics_connection.set_suite_settings(
            name=name, args=args, timeout=time_to_seconds(timeout, round_to=0)
        )

    def get_recent_result_of_plan(self, timeout=10):
        """
        Get paths of recent plan result files.

        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: List[str]: a list of paths of recent plan result files
        """
        return self._defensics_connection.get_recent_result_of_plan(timeout=time_to_seconds(timeout, round_to=0))

    def get_recent_result_of_suite(self, timeout=10):
        """
        Get paths of recent suite result files.

        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: List[str]: a list of paths of recent suite result files
        """
        return self._defensics_connection.get_recent_result_of_suite(timeout=time_to_seconds(timeout, round_to=0))

    def save_result(self, dest_dir, file_path, name=None, timeout=60):
        """
        Save a specific file from the results in a local directory

        File can be defined as an absolute file or a relative file to current result directory.
        If `name` argument is used, the recent result dir is used and result files can be addressed with filename only.

        Examples:
            ``Save Result    /home/ute/    /root/synopsys/defensics/results/HTTP-Server/20200528-1318-23/main.log``

            ``Save Result    /home/ute/    HTTP-Server/20200528-1318-23/main.log``

            ``Save Result    /home/ute/    main.log    http``

        :param str dest_dir: local directory path where the file will be saved
        :param str file_path: path to file to be downloaded
        :param Optional[str] name: short name of the suite
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return:
        """
        return self._defensics_connection.save_result(
            dest_dir=dest_dir, file_path=file_path, name=name, timeout=time_to_seconds(timeout, round_to=0)
        )

    def save_report(self, dest_dir, result_dir, report_type="zip", timeout=60):
        """
        Save report.

        Possible report types are

        * ``single-html``: Report as single html page
        * ``zip``: HTML report packed to ZIP
        * ``remediation``: For remediation package

        :param str dest_dir: local directory path where the report will be saved
        :param str result_dir: e.g., ``HTTP-Server/20200528-1318-23``,
            ``/root/synopsys/defensics/results/HTTP-Server/20200528-1318-23``
        :param Optional[str] report_type: type of report to be generated (``zip`` is default)
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return:
        """
        return self._defensics_connection.save_report(
            dest_dir=dest_dir,
            result_dir=result_dir,
            report_type=report_type,
            timeout=time_to_seconds(timeout, round_to=0),
        )

    def start_interoperability_probe(self, name=None, apply_flag=True, timeout=10):
        """
        This method starts a test run that executes valid cases and generates test groups according to the
        interoperating valid cases. Note that probe cannot be made for suite that is already running.

        :param Optional[str] name: Name of the probed test suite. Optional if there is only one loaded suite.
        :param Optional[bool] apply_flag: ``True`` if the test groups are generated after probe. If not defined,
            ``true`` is used. Using ``false`` makes it possible to probe SUT more quickly as test case generating
            takes time.
        :param Optional[Union[int,str]] timeout: Timeout for the operation
        :return: It returns the parsed xml probe result in a form of ``InteroperabilityProbe`` object.
        """
        return self._defensics_connection.start_interoperability_probe(
            name=name, apply_flag=apply_flag, timeout=time_to_seconds(timeout, round_to=0)
        )

    def get_result_of_previous_interoperability_probe(self, timeout=10):
        """
        This method returns result of the finished previous probe

        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: It returns the parsed xml last probe result in a form of ``InteroperabilityProbe`` object.
        """
        return self._defensics_connection.get_result_of_previous_interoperability_probe(
            timeout=time_to_seconds(timeout, round_to=0)
        )

    def unload_suite(self, name, timeout=30):
        """
        Unload a suite to clean up the server state for possible next user.

        :param str name: suite name, or short name e.g., ``HTTP-Server``, ``http``
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return:
        """
        return self._defensics_connection.unload_suite(name=name, timeout=time_to_seconds(timeout, round_to=0))

    def kill_server(self, timeout=10):
        """
        This method shuts down all suites and http server.

        :param Optional[Union[int,str]] timeout: Timeout for the operation
        :return: str: Returns string confirming that server has been closed
        """
        return self._defensics_connection.kill_server(timeout=time_to_seconds(timeout, round_to=0))

    def check_all_licenses(self, timeout=600):
        """
        Check the license for a all installed suites.

        :param Optional[Union[int,str]] timeout: Timeout for the operation
        :return: str: info string with licence details for all suites
        """
        return self._defensics_connection.check_all_licenses(timeout=time_to_seconds(timeout, round_to=0))

    def check_license(self, suite, timeout=60):
        """
        Check the license for a single suite.

        :param str suite: suite to check, e.g., ``diameter-client-300.jar``,
            ``/opt/Synopsys/Defensics/bt-a2dp-5.3.0/testtool/bt-a2dp-530.jar``
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: str: info string, e.g.,
            ``License found for /opt/Synopsys/Defensics/bt-a2dp-5.3.0/testtool/bt-a2dp-530.jar
            License (flex full) d3-bt-a2dp expiry Mon May 01 00:00:00 CEST 2023``
        """
        return self._defensics_connection.check_license(suite, timeout=time_to_seconds(timeout, round_to=0))

    def load_plan(self, plan, timeout=30):
        """
        Load plan by name.

        Loading a test plan causes unloading of other suites loaded before the test plan.

        :param str plan: plan to load, e.g., ``ip4.testplan``
        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: str: info string, e.g., ``Loading test plan ip4.testplan``
        """
        return self._defensics_connection.load_plan(plan, timeout=time_to_seconds(timeout, round_to=0))

    def get_plan_status(self, timeout=10):
        """
        Get testing status.

        :param Optional[Union[int,str]] timeout: Timeout for the operation in seconds or as a time string,
            e.g., ``30``, ``2m``, ``5 minutes``
        :return: str: plan status, e.g., ``loaded``, ``starting``, ``running``, ``error``, etc.
        """
        return self._defensics_connection.get_plan_status(timeout=time_to_seconds(timeout, round_to=0))
